\begin{theorem}[4.4.3]
\label{III.4.4.3}
\textnormal{(``Teorema principal'' de Zariski).}
Sea $Y$ un esquema noetheriano, sea $f:X\to Y$ un morfismo
cuasiproyectivo, y sea $X'$ el conjunto de puntos $x\in X$ que están
aislados en su fibra $f^{-1}(f(x))$. Entonces $X'$ es una parte abierta de $X$ sobre $X'$ es isomorfo a un
subesquema inducido sobre un subconjunto abierto de un $Y$-esquema
$Y'$ finito sobre $Y$.
\end{theorem}

\begin{proof}
Existe un $Y$-esquema proyectivo $Z$ tal que $X$ es
$Y$-isomorfo al subesquema inducido sobre un subconjunto abierto de
$Z$ (\textbf{II}, 5.3.2 y 5.5.1). Se reduce pues a demostrar el teorema cuando $f$ es proyectivo, luego propio \sref[II]{II.5.5.3}, y el
teorema se sigue inmediatamente de
\sref{III.4.4.1}.
\end{proof}

after:
\begin{theorem}[4.4.3]
\label{III.4.4.3-fr}
\textnormal{(«Teorema principal» de Zariski).}
Sean $Y$ un preesquema noetheriano, $f:X\to Y$ un morfismo cuasiproyectivo,
$X'$ el conjunto de los puntos $x\in X$ que están aislados en su fibra
$f^{-1}(f(x))$. Entonces $X'$ es una parte abierta de $X$, y el
subpreesquema inducido $X'$ es isomorfo a un preesquema inducido sobre una parte
abierta de un $Y$-preesquema $Y'$ finito sobre $Y$.
\end{theorem}

\begin{proof}
La hipótesis implica que existe un $Y$-preesquema proyectivo $Z$ tal que $X$
sea $Y$-isomorfo a un subpreesquema inducido sobre un abierto de $Z$
(\textbf{II}, 5.3.2 y 5.5.1). Se reduce pues a demostrar el teorema cuando $f$
es un morfismo proyectivo, luego propio (\textbf{II}, 5.5.3), y resulta entonces
inmediatamente de (\hyperref[III.4.4.1-fr]{4.4.1}).
\end{proof}

